//! Cross-field validation for `sw-launch.toml`, schema v1.2.
//!
//! Each rule has a stable error code (E0001..E0034). The full
//! catalogue is in `docs/design.md` "Validation rules". The codes
//! never change meaning; rules added later get new codes.
//!
//! `validate(&Config, scenario_name)` collects every diagnostic
//! before returning; callers decide whether to fail-fast or report
//! all. `cli::check` reports all and exits non-zero if any error-
//! severity diagnostic was emitted.
//!
//! Rules that require artifact sizes (overlap of byte ranges
//! resolved through listings) or vendor lockfile state (E0019
//! sidecar staleness) are stubbed at this step and re-enabled by
//! later steps as their infrastructure lands.

use std::collections::{BTreeMap, BTreeSet};
use std::fmt;

use crate::config::{
    Budget, Config, HeapCategory, HexValue, Layer, LoadMethod, MemoryProfile, MemRegionKind,
    Partition, Patch, Scenario, Segment, SegmentKind, SizeOrAuto,
};
use crate::error::ErrorCode;

/// Severity for a diagnostic. Errors fail the run; warnings are
/// reported but do not change exit status unless `--strict`.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Severity {
    Error,
    Warning,
}

/// A single validation finding. Each `code` is stable; agents may
/// pattern-match on the numeric form.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Diagnostic {
    pub code: ErrorCode,
    pub severity: Severity,
    pub layer: Option<String>,
    pub segment: Option<String>,
    pub message: String,
    pub hint: Option<String>,
}

impl fmt::Display for Diagnostic {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let sev = match self.severity {
            Severity::Error => "error",
            Severity::Warning => "warning",
        };
        write!(f, "{sev}[{}]: {}", self.code, self.message)?;
        if let Some(layer) = &self.layer {
            write!(f, "\n  layer: {layer}")?;
        }
        if let Some(segment) = &self.segment {
            write!(f, "\n  segment: {segment}")?;
        }
        if let Some(hint) = &self.hint {
            write!(f, "\n  hint: {hint}")?;
        }
        Ok(())
    }
}

/// Validate a single scenario. Returns Ok if there are no errors;
/// always returns the full diagnostic list (warnings included)
/// in `Err` if any error severity was emitted, so callers can
/// print everything and still exit non-zero on errors only.
pub fn validate(cfg: &Config, scenario_name: &str) -> Result<Vec<Diagnostic>, Vec<Diagnostic>> {
    let mut out = Vec::new();
    let scen = match cfg.scenarios.get(scenario_name) {
        Some(s) => s,
        None => {
            out.push(Diagnostic {
                code: ErrorCode(2),
                severity: Severity::Error,
                layer: None,
                segment: None,
                message: format!("scenario `{scenario_name}` not declared"),
                hint: None,
            });
            return Err(out);
        }
    };
    check_scenario_structural(cfg, scenario_name, scen, &mut out);
    check_layers(cfg, scen, &mut out);
    check_profile_resolution(cfg, scenario_name, scen, &mut out);
    check_segment_shapes(cfg, scen, &mut out);
    check_heap_budgets(cfg, scen, &mut out);
    check_total_rule_of_thumb(cfg, scen, &mut out);

    if out.iter().any(|d| d.severity == Severity::Error) {
        Err(out)
    } else {
        Ok(out)
    }
}

// ---------- E0001..E0009: structural --------------------------------

fn check_scenario_structural(
    cfg: &Config,
    scenario_name: &str,
    scen: &Scenario,
    out: &mut Vec<Diagnostic>,
) {
    if scen.layers.is_empty() {
        out.push(err(ErrorCode(1), format!(
            "scenario `{scenario_name}` declares no layers"
        )));
    }
    let run = scen.run.as_ref();
    let has_halt = run.and_then(|r| r.halt_on.as_ref()).is_some();
    let has_max = run.and_then(|r| r.max_cycles).is_some();
    if !has_halt && !has_max {
        out.push(err_with_hint(
            ErrorCode(8),
            format!("scenario `{scenario_name}` has no halt_on or max_cycles"),
            "set [scenarios.<name>.run].halt_on or .max_cycles".into(),
        ));
    }
    if !cfg.targets.contains_key(&scen.target) {
        out.push(err(
            ErrorCode(2),
            format!(
                "scenario `{scenario_name}` references undeclared target `{}`",
                scen.target
            ),
        ));
    }
}

fn check_layers(cfg: &Config, scen: &Scenario, out: &mut Vec<Diagnostic>) {
    for name in &scen.layers {
        let Some(layer) = cfg.layers.get(name) else {
            out.push(err(
                ErrorCode(2),
                format!("scenario references undeclared layer `{name}`"),
            ));
            continue;
        };
        check_kind_load_compat(name, layer, out);
        check_uart_size(name, layer, out);
        check_patch_targets(name, layer, out);
        check_patch_self_outside_segment(name, layer, out);
    }
}

fn check_kind_load_compat(name: &str, layer: &Layer, out: &mut Vec<Diagnostic>) {
    let Some(load) = &layer.load else { return };
    let kind = layer.kind.as_str();
    let bad_uart = matches!(kind, "assembler" | "binary" | "pcode" | "pcode-image" | "composite")
        && load.method == LoadMethod::Uart;
    if bad_uart {
        out.push(layer_err(
            ErrorCode(5),
            name,
            format!("kind `{kind}` cannot use load.method = \"uart\""),
        ));
    }
    if load.method == LoadMethod::Uart && load.max_bytes.is_none() {
        out.push(layer_err_with_hint(
            ErrorCode(4),
            name,
            "uart layer is missing load.max_bytes".into(),
            "set load.max_bytes = <hard cap>".into(),
        ));
    }
    if load.method == LoadMethod::Memory
        && load.address.is_none()
        && !layer.absolute_addresses
    {
        // Partition-relative layers will resolve via segments;
        // absolute_addresses=false without address is ok if segments cover it.
        // Flag only if the layer has no segments either.
        if layer.segments.is_empty() {
            out.push(layer_err_with_hint(
                ErrorCode(15),
                name,
                "memory load with no address and no segments".into(),
                "set load.address or declare segments with claims".into(),
            ));
        }
    }
}

fn check_uart_size(name: &str, layer: &Layer, out: &mut Vec<Diagnostic>) {
    let Some(load) = &layer.load else { return };
    if load.method != LoadMethod::Uart {
        return;
    }
    let Some(max_bytes) = load.max_bytes else {
        return;
    };
    if let Some(input) = &layer.input {
        if let Ok(meta) = std::fs::metadata(input) {
            if meta.len() > max_bytes {
                out.push(layer_err(
                    ErrorCode(4),
                    name,
                    format!(
                        "uart input `{input}` ({} bytes) exceeds max_bytes ({max_bytes})",
                        meta.len()
                    ),
                ));
            }
        }
    }
}

fn check_patch_targets(name: &str, layer: &Layer, out: &mut Vec<Diagnostic>) {
    for p in &layer.patches {
        if p.target.starts_with("0x") {
            // Literal hex; verify it parses.
            if crate::config::parse_hex_u32(&p.target).is_err() {
                out.push(layer_err(
                    ErrorCode(6),
                    name,
                    format!("patch target `{}` is not a valid hex address", p.target),
                ));
            }
        }
        // Symbolic targets (`<layer>.<symbol>`) are deferred to
        // step 007 (assembler-tool / listing parser). We only
        // verify that the referenced layer exists so a typo is
        // caught now.
        if let Some((other, _)) = p.target.split_once('.') {
            if !other.starts_with("0x") && !layer_or_alias_exists(other, layer, name) {
                // Loosely check; more thorough resolution in step 007.
                if !is_known_layer_alias(other) {
                    // Defer: can't know without cfg here. See step 007.
                }
            }
        }
        check_patch_value(name, p, out);
    }
}

fn check_patch_value(name: &str, p: &Patch, out: &mut Vec<Diagnostic>) {
    let v = p.value.as_str();
    if v == "self.address" || v == "self.end" || v == "self.size" {
        // E0016 is enforced separately (must be inside a segment).
        return;
    }
    if v.starts_with("0x") && crate::config::parse_hex_u32(v).is_err() {
        out.push(layer_err(
            ErrorCode(6),
            name,
            format!("patch value `{v}` is not a valid hex literal"),
        ));
    }
}

fn check_patch_self_outside_segment(name: &str, layer: &Layer, out: &mut Vec<Diagnostic>) {
    for p in &layer.patches {
        let v = p.value.as_str();
        if v == "self.address" || v == "self.end" || v == "self.size" {
            out.push(layer_err_with_hint(
                ErrorCode(16),
                name,
                format!("patch value `{v}` only valid inside a segment block"),
                "move this patch into a [[layers.<n>.segments]] entry".into(),
            ));
        }
    }
}

fn layer_or_alias_exists(_other: &str, _layer: &Layer, _layer_name: &str) -> bool {
    // Real cross-layer resolution lands in step 007.
    true
}

fn is_known_layer_alias(_name: &str) -> bool {
    true
}

// ---------- E0011..E0016: segment shapes ----------------------------

fn check_segment_shapes(cfg: &Config, scen: &Scenario, out: &mut Vec<Diagnostic>) {
    let target = cfg.targets.get(&scen.target);
    for layer_name in &scen.layers {
        let Some(layer) = cfg.layers.get(layer_name) else {
            continue;
        };
        for seg in &layer.segments {
            check_segment_size(layer_name, seg, out);
            check_segment_embedded(layer_name, seg, out);
            check_segment_in_target_regions(layer_name, seg, target, out);
        }
    }
}

fn check_segment_size(layer_name: &str, seg: &Segment, out: &mut Vec<Diagnostic>) {
    if !matches!(seg.kind, SegmentKind::Stack | SegmentKind::Heap | SegmentKind::Bss) {
        return;
    }
    let nonzero = match &seg.size {
        Some(SizeOrAuto::Hex(h)) if h.0 == "auto" => true,
        Some(SizeOrAuto::Hex(h)) => h.as_u32().map(|v| v > 0).unwrap_or(false),
        None => false,
    };
    if !nonzero {
        out.push(layer_seg_err(
            ErrorCode(13),
            layer_name,
            seg.name.as_deref(),
            "stack/heap/bss segment must have nonzero size".into(),
        ));
    }
}

fn check_segment_embedded(layer_name: &str, seg: &Segment, out: &mut Vec<Diagnostic>) {
    match seg.embedded {
        Some(true) => {
            if seg.symbol.is_none() {
                out.push(layer_seg_err_with_hint(
                    ErrorCode(14),
                    layer_name,
                    seg.name.as_deref(),
                    "embedded = true segment must declare `symbol`".into(),
                    "set symbol = \"<label-in-source>\"".into(),
                ));
            }
        }
        Some(false) => {
            let has_addr = seg
                .load
                .as_ref()
                .and_then(|l| l.address.as_ref())
                .is_some();
            let has_claims = !seg.claims.is_empty();
            let has_size = seg.size.is_some();
            if !has_size {
                out.push(layer_seg_err_with_hint(
                    ErrorCode(15),
                    layer_name,
                    seg.name.as_deref(),
                    "embedded = false segment must declare `size`".into(),
                    "set size = \"0x...\"".into(),
                ));
            }
            if !has_addr && !has_claims {
                out.push(layer_seg_err_with_hint(
                    ErrorCode(15),
                    layer_name,
                    seg.name.as_deref(),
                    "embedded = false segment needs load.address or claims = [...]".into(),
                    "either set load.address or claim a (partition, region) cell".into(),
                ));
            }
        }
        None => {}
    }
}

fn check_segment_in_target_regions(
    layer_name: &str,
    seg: &Segment,
    target: Option<&crate::config::Target>,
    out: &mut Vec<Diagnostic>,
) {
    let Some(target) = target else { return };
    let Some(load) = &seg.load else { return };
    let Some(addr_hex) = &load.address else { return };
    let Ok(addr) = addr_hex.as_u32() else { return };
    let Some(end) = seg
        .size
        .as_ref()
        .and_then(SizeOrAuto::as_hex)
        .and_then(|h| h.as_u32().ok())
        .map(|sz| addr + sz)
    else {
        return;
    };

    let r = &target.regions;
    let in_sram = inside(addr, end, &r.sram);
    let touches_ebr = overlaps(addr, end, &r.ebr_stack);
    let touches_mmio = overlaps(addr, end, &r.mmio);
    if !in_sram || touches_ebr || touches_mmio {
        out.push(layer_seg_err(
            ErrorCode(11),
            layer_name,
            seg.name.as_deref(),
            format!(
                "segment range [0x{addr:06X}..0x{end:06X}) escapes SRAM or touches reserved regions"
            ),
        ));
    }
}

fn inside(addr: u32, end: u32, range: &crate::config::MemRange) -> bool {
    let lo = range.start.as_u32().unwrap_or(0);
    let hi = range.end.as_u32().unwrap_or(0);
    addr >= lo && end <= hi.saturating_add(1)
}

fn overlaps(addr: u32, end: u32, range: &crate::config::MemRange) -> bool {
    let lo = range.start.as_u32().unwrap_or(0);
    let hi = range.end.as_u32().unwrap_or(0);
    !(end <= lo || addr > hi)
}

// ---------- E0028..E0034: budgets and profile resolution -----------

fn check_profile_resolution(
    cfg: &Config,
    scenario_name: &str,
    scen: &Scenario,
    out: &mut Vec<Diagnostic>,
) {
    let Some(prof_name) = scen.memory_profile.as_ref() else {
        return;
    };
    let Some(profile) = cfg.memory_profiles.get(prof_name) else {
        out.push(err_with_hint(
            ErrorCode(31),
            format!(
                "scenario `{scenario_name}` references undeclared memory_profile `{prof_name}`"
            ),
            format!("declare [memory_profiles.{prof_name}] or pick another profile"),
        ));
        return;
    };
    check_profile_partitions(prof_name, profile, out);
    check_layer_claims_match_profile(cfg, scen, profile, out);
}

fn check_profile_partitions(prof_name: &str, profile: &MemoryProfile, out: &mut Vec<Diagnostic>) {
    // E0033: profile partitions must not overlap.
    let mut ranges: Vec<(String, u32, u32)> = Vec::new();
    for p in &profile.partitions {
        let (Ok(base), Ok(size)) = (p.base.as_u32(), p.size.as_u32()) else {
            continue;
        };
        ranges.push((p.name.clone(), base, base.saturating_add(size)));
    }
    ranges.sort_by_key(|r| r.1);
    for w in ranges.windows(2) {
        if w[1].1 < w[0].2 {
            out.push(err(
                ErrorCode(33),
                format!(
                    "memory_profile `{prof_name}` partitions `{}` and `{}` overlap",
                    w[0].0, w[1].0
                ),
            ));
        }
    }
}

fn check_layer_claims_match_profile(
    cfg: &Config,
    scen: &Scenario,
    profile: &MemoryProfile,
    out: &mut Vec<Diagnostic>,
) {
    let mut available: BTreeMap<&str, BTreeSet<&str>> = BTreeMap::new();
    for p in &profile.partitions {
        let regs: BTreeSet<&str> = p.regions.iter().map(|r| r.name.as_str()).collect();
        available.insert(p.name.as_str(), regs);
    }
    for layer_name in &scen.layers {
        let Some(layer) = cfg.layers.get(layer_name) else {
            continue;
        };
        if layer.absolute_addresses {
            continue;
        }
        for seg in &layer.segments {
            for claim in &seg.claims {
                let (Some(part), Some(region)) = (&claim.partition, &claim.region) else {
                    continue;
                };
                let ok = available
                    .get(part.as_str())
                    .map(|rs| rs.contains(region.as_str()))
                    .unwrap_or(false);
                if !ok {
                    out.push(layer_seg_err_with_hint(
                        ErrorCode(32),
                        layer_name,
                        seg.name.as_deref(),
                        format!(
                            "claim ({part}, {region}) not in profile partitions/regions"
                        ),
                        format!("available: {available:?}"),
                    ));
                }
            }
        }
    }
}

fn check_heap_budgets(cfg: &Config, scen: &Scenario, out: &mut Vec<Diagnostic>) {
    let Some(prof_name) = scen.memory_profile.as_ref() else {
        return;
    };
    let Some(profile) = cfg.memory_profiles.get(prof_name) else {
        return;
    };
    let Some(budget) = profile.budget.as_ref() else {
        return;
    };
    let mut heap_total: u64 = 0;
    for layer_name in &scen.layers {
        let Some(layer) = cfg.layers.get(layer_name) else {
            continue;
        };
        let layer_heap = layer_heap_size(layer);
        if layer_heap > 32 * 1024 && layer.heap_justification.is_none() {
            out.push(layer_err_with_hint(
                ErrorCode(30),
                layer_name,
                format!(
                    "layer claims heap > 32 KiB ({layer_heap} bytes) without heap_justification"
                ),
                "add [layers.<n>.heap_justification] with category + note".into(),
            ));
        }
        if let Some(j) = &layer.heap_justification {
            if matches!(
                j.category,
                HeapCategory::DeadLeak | HeapCategory::AlgorithmicBloat
            ) {
                out.push(Diagnostic {
                    code: ErrorCode(30),
                    severity: Severity::Warning,
                    layer: Some(layer_name.clone()),
                    segment: None,
                    message: format!(
                        "heap_justification.category = {:?}; --strict will reject",
                        j.category
                    ),
                    hint: Some("address the underlying issue (GC, refactor) instead".into()),
                });
            }
        }
        heap_total += u64::from(layer_heap);
    }
    let Ok(budget_max) = budget.heap_max.as_u32() else {
        return;
    };
    let bm = u64::from(budget_max);
    if heap_total > bm {
        out.push(err(
            ErrorCode(28),
            format!(
                "scenario heap claims ({heap_total} bytes) exceed budget.heap_max ({bm} bytes)"
            ),
        ));
    } else if heap_total * 5 > bm * 4 {
        out.push(Diagnostic {
            code: ErrorCode(29),
            severity: Severity::Warning,
            layer: None,
            segment: None,
            message: format!(
                "scenario heap claims ({heap_total} bytes) above 80% of budget ({bm} bytes)"
            ),
            hint: Some("verify the layer is not silently bloating".into()),
        });
    }
}

fn layer_heap_size(layer: &Layer) -> u32 {
    let mut total: u32 = 0;
    for seg in &layer.segments {
        if !matches!(seg.kind, SegmentKind::Heap) {
            continue;
        }
        if let Some(h) = seg.size.as_ref().and_then(SizeOrAuto::as_hex) {
            total = total.saturating_add(h.as_u32().unwrap_or(0));
        }
    }
    total
}

fn check_total_rule_of_thumb(cfg: &Config, scen: &Scenario, out: &mut Vec<Diagnostic>) {
    let one_mib: u64 = 0x100000;
    let mut total: u64 = 0;
    for layer_name in &scen.layers {
        let Some(layer) = cfg.layers.get(layer_name) else {
            continue;
        };
        if layer.acknowledge_oversized {
            continue;
        }
        for seg in &layer.segments {
            if let Some(h) = seg.size.as_ref().and_then(SizeOrAuto::as_hex) {
                total = total.saturating_add(u64::from(h.as_u32().unwrap_or(0)));
            }
        }
    }
    if total > one_mib {
        out.push(Diagnostic {
            code: ErrorCode(34),
            severity: Severity::Warning,
            layer: None,
            segment: None,
            message: format!(
                "scenario claims {total} bytes total; rule of thumb is <= 1 MiB"
            ),
            hint: Some("set acknowledge_oversized = true on the offending layer to silence".into()),
        });
    }
}

// ---------- helpers ------------------------------------------------

fn err(code: ErrorCode, message: String) -> Diagnostic {
    Diagnostic {
        code,
        severity: Severity::Error,
        layer: None,
        segment: None,
        message,
        hint: None,
    }
}

fn err_with_hint(code: ErrorCode, message: String, hint: String) -> Diagnostic {
    Diagnostic {
        code,
        severity: Severity::Error,
        layer: None,
        segment: None,
        message,
        hint: Some(hint),
    }
}

fn layer_err(code: ErrorCode, layer: &str, message: String) -> Diagnostic {
    Diagnostic {
        code,
        severity: Severity::Error,
        layer: Some(layer.into()),
        segment: None,
        message,
        hint: None,
    }
}

fn layer_err_with_hint(code: ErrorCode, layer: &str, message: String, hint: String) -> Diagnostic {
    Diagnostic {
        code,
        severity: Severity::Error,
        layer: Some(layer.into()),
        segment: None,
        message,
        hint: Some(hint),
    }
}

fn layer_seg_err(
    code: ErrorCode,
    layer: &str,
    segment: Option<&str>,
    message: String,
) -> Diagnostic {
    Diagnostic {
        code,
        severity: Severity::Error,
        layer: Some(layer.into()),
        segment: segment.map(String::from),
        message,
        hint: None,
    }
}

fn layer_seg_err_with_hint(
    code: ErrorCode,
    layer: &str,
    segment: Option<&str>,
    message: String,
    hint: String,
) -> Diagnostic {
    Diagnostic {
        code,
        severity: Severity::Error,
        layer: Some(layer.into()),
        segment: segment.map(String::from),
        message,
        hint: Some(hint),
    }
}

