fn check_heap_budgets(cfg: &Config, scen: &Scenario, out: &mut Vec<Diagnostic>) {
    let Some(prof_name) = scen.memory_profile.as_ref() else {
        return;
    };
    let Some(profile) = cfg.memory_profiles.get(prof_name) else {
        return;
    };
    let Some(budget) = profile.budget.as_ref() else {
        return;
    };
    let mut heap_total: u64 = 0;
    for layer_name in &scen.layers {
        let Some(layer) = cfg.layers.get(layer_name) else {
            continue;
        };
        let layer_heap = layer_heap_size(layer);
        if layer_heap > 32 * 1024 && layer.heap_justification.is_none() {
            out.push(layer_err_with_hint(
                ErrorCode(30),
                layer_name,
                format!(
                    "layer claims heap > 32 KiB ({layer_heap} bytes) without heap_justification"
                ),
                "add [layers.<n>.heap_justification] with category + note".into(),
            ));
        }
        if let Some(j) = &layer.heap_justification {
            if matches!(
                j.category,
                HeapCategory::DeadLeak | HeapCategory::AlgorithmicBloat
            ) {
                out.push(Diagnostic {
                    code: ErrorCode(30),
                    severity: Severity::Warning,
                    layer: Some(layer_name.clone()),
                    segment: None,
                    message: format!(
                        "heap_justification.category = {:?}; --strict will reject",
                        j.category
                    ),
                    hint: Some("address the underlying issue (GC, refactor) instead".into()),
                });
            }
        }
        heap_total += u64::from(layer_heap);
    }
    let Ok(budget_max) = budget.heap_max.as_u32() else {
        return;
    };
    let bm = u64::from(budget_max);
    if heap_total > bm {
        out.push(err(
            ErrorCode(28),
            format!(
                "scenario heap claims ({heap_total} bytes) exceed budget.heap_max ({bm} bytes)"
            ),
        ));
    } else if heap_total * 5 > bm * 4 {
        out.push(Diagnostic {
            code: ErrorCode(29),
            severity: Severity::Warning,
            layer: None,
            segment: None,
            message: format!(
                "scenario heap claims ({heap_total} bytes) above 80% of budget ({bm} bytes)"
            ),
            hint: Some("verify the layer is not silently bloating".into()),
        });
    }
}

