//! `Diagnostic`, `Severity`, and the small set of constructors
//! used throughout the validators.

use std::fmt;

use crate::error::ErrorCode;

/// Severity for a diagnostic. Errors fail the run; warnings are
/// reported but do not change exit status unless `--strict`.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Severity {
    Error,
    Warning,
}

/// A single validation finding. Each `code` is stable; agents may
/// pattern-match on the numeric form.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Diagnostic {
    pub code: ErrorCode,
    pub severity: Severity,
    pub layer: Option<String>,
    pub segment: Option<String>,
    pub message: String,
    pub hint: Option<String>,
}

impl fmt::Display for Diagnostic {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let sev = match self.severity {
            Severity::Error => "error",
            Severity::Warning => "warning",
        };
        write!(f, "{sev}[{}]: {}", self.code, self.message)?;
        if let Some(layer) = &self.layer {
            write!(f, "\n  layer: {layer}")?;
        }
        if let Some(segment) = &self.segment {
            write!(f, "\n  segment: {segment}")?;
        }
        if let Some(hint) = &self.hint {
            write!(f, "\n  hint: {hint}")?;
        }
        Ok(())
    }
}

pub(super) fn err(code: ErrorCode, message: String) -> Diagnostic {
    Diagnostic {
        code,
        severity: Severity::Error,
        layer: None,
        segment: None,
        message,
        hint: None,
    }
}

pub(super) fn err_with_hint(code: ErrorCode, message: String, hint: String) -> Diagnostic {
    Diagnostic {
        code,
        severity: Severity::Error,
        layer: None,
        segment: None,
        message,
        hint: Some(hint),
    }
}

pub(super) fn layer_err(code: ErrorCode, layer: &str, message: String) -> Diagnostic {
    Diagnostic {
        code,
        severity: Severity::Error,
        layer: Some(layer.into()),
        segment: None,
        message,
        hint: None,
    }
}

pub(super) fn layer_err_with_hint(
    code: ErrorCode,
    layer: &str,
    message: String,
    hint: String,
) -> Diagnostic {
    Diagnostic {
        code,
        severity: Severity::Error,
        layer: Some(layer.into()),
        segment: None,
        message,
        hint: Some(hint),
    }
}

pub(super) fn layer_seg_err(
    code: ErrorCode,
    layer: &str,
    segment: Option<&str>,
    message: String,
) -> Diagnostic {
    Diagnostic {
        code,
        severity: Severity::Error,
        layer: Some(layer.into()),
        segment: segment.map(String::from),
        message,
        hint: None,
    }
}

pub(super) fn layer_seg_err_with_hint(
    code: ErrorCode,
    layer: &str,
    segment: Option<&str>,
    message: String,
    hint: String,
) -> Diagnostic {
    Diagnostic {
        code,
        severity: Severity::Error,
        layer: Some(layer.into()),
        segment: segment.map(String::from),
        message,
        hint: Some(hint),
    }
}

