58	fn check_layer_claims_match_profile(
59	    cfg: &Config,
60	    scen: &Scenario,
61	    profile: &MemoryProfile,
62	    out: &mut Vec<Diagnostic>,
63	) {
64	    let mut available: BTreeMap<&str, BTreeSet<&str>> = BTreeMap::new();
65	    for p in &profile.partitions {
66	        let regs: BTreeSet<&str> = p.regions.iter().map(|r| r.name.as_str()).collect();
67	        available.insert(p.name.as_str(), regs);
68	    }
69	    for layer_name in &scen.layers {
70	        let Some(layer) = cfg.layers.get(layer_name) else {
71	            continue;
72	        };
73	        if layer.absolute_addresses {
74	            continue;
75	        }
76	        for seg in &layer.segments {
77	            for claim in &seg.claims {
78	                let (Some(part), Some(region)) = (&claim.partition, &claim.region) else {
79	                    continue;
80	                };
81	                let ok = available
82	                    .get(part.as_str())
83	                    .map(|rs| rs.contains(region.as_str()))
84	                    .unwrap_or(false);
85	                if !ok {
86	                    out.push(layer_seg_err_with_hint(
87	                        ErrorCode(32),
88	                        layer_name,
89	                        seg.name.as_deref(),
90	                        format!("claim ({part}, {region}) not in profile partitions/regions"),
91	                        format!("available: {available:?}"),
92	                    ));
93	                }
94	            }
95	        }
96	    }
97	}
