99	pub(super) fn check_oversized_heaps_need_justification(
100	    cfg: &Config,
101	    scen: &Scenario,
102	    out: &mut Vec<Diagnostic>,
103	) {
104	    for layer_name in &scen.layers {
105	        let Some(layer) = cfg.layers.get(layer_name) else {
106	            continue;
107	        };
108	        let layer_heap = layer_heap_size(layer);
109	        if layer_heap > 32 * 1024 && layer.heap_justification.is_none() {
110	            out.push(layer_err_with_hint(
