169	        out.push(Diagnostic {
170	            code: ErrorCode(29),
171	            severity: Severity::Warning,
172	            layer: None,
173	            segment: None,
174	            message: format!(
175	                "scenario heap claims ({heap_total} bytes) above 80% of budget ({bm} bytes)"
176	            ),
177	            hint: Some("verify the layer is not silently bloating".into()),
178	        });
179	    }
180	}
