1	//! Segment shape rules E0011..E0016: SRAM/EBR/MMIO containment,
2	//! nonzero size, embedded vs reserved invariants.
3	
4	use super::diagnostic::{Diagnostic, layer_seg_err, layer_seg_err_with_hint};
5	use crate::config::{Config, MemRange, Scenario, Segment, SegmentKind, SizeOrAuto, Target};
6	use crate::error::ErrorCode;
7	
8	pub(super) fn check_segment_shapes(cfg: &Config, scen: &Scenario, out: &mut Vec<Diagnostic>) {
9	    let target = cfg.targets.get(&scen.target);
10	    for layer_name in &scen.layers {
11	        let Some(layer) = cfg.layers.get(layer_name) else {
12	            continue;
13	        };
14	        for seg in &layer.segments {
15	            check_segment_size(layer_name, seg, out);
16	            check_segment_embedded(layer_name, seg, out);
17	            check_segment_in_target_regions(layer_name, seg, target, out);
18	        }
19	    }
20	}
21	
22	fn check_segment_size(layer_name: &str, seg: &Segment, out: &mut Vec<Diagnostic>) {
23	    if !matches!(
24	        seg.kind,
25	        SegmentKind::Stack | SegmentKind::Heap | SegmentKind::Bss
26	    ) {
27	        return;
28	    }
29	    let nonzero = match &seg.size {
30	        Some(SizeOrAuto::Hex(h)) if h.0 == "auto" => true,
31	        Some(SizeOrAuto::Hex(h)) => h.as_u32().map(|v| v > 0).unwrap_or(false),
32	        None => false,
33	    };
34	    if !nonzero {
35	        out.push(layer_seg_err(
36	            ErrorCode(13),
37	            layer_name,
38	            seg.name.as_deref(),
39	            "stack/heap/bss segment must have nonzero size".into(),
40	        ));
41	    }
42	}
43	
44	fn check_segment_embedded(layer_name: &str, seg: &Segment, out: &mut Vec<Diagnostic>) {
45	    match seg.embedded {
46	        Some(true) => {
47	            if seg.symbol.is_none() {
48	                out.push(layer_seg_err_with_hint(
49	                    ErrorCode(14),
50	                    layer_name,
51	                    seg.name.as_deref(),
52	                    "embedded = true segment must declare `symbol`".into(),
53	                    "set symbol = \"<label-in-source>\"".into(),
54	                ));
55	            }
56	        }
57	        Some(false) => {
58	            let has_addr = seg.load.as_ref().and_then(|l| l.address.as_ref()).is_some();
59	            let has_claims = !seg.claims.is_empty();
60	            let has_size = seg.size.is_some();
61	            if !has_size {
62	                out.push(layer_seg_err_with_hint(
63	                    ErrorCode(15),
64	                    layer_name,
65	                    seg.name.as_deref(),
66	                    "embedded = false segment must declare `size`".into(),
67	                    "set size = \"0x...\"".into(),
68	                ));
69	            }
70	            if !has_addr && !has_claims {
71	                out.push(layer_seg_err_with_hint(
72	                    ErrorCode(15),
73	                    layer_name,
74	                    seg.name.as_deref(),
75	                    "embedded = false segment needs load.address or claims = [...]".into(),
76	                    "either set load.address or claim a (partition, region) cell".into(),
77	                ));
78	            }
79	        }
80	        None => {}
81	    }
82	}
83	
84	fn check_segment_in_target_regions(
85	    layer_name: &str,
86	    seg: &Segment,
87	    target: Option<&Target>,
88	    out: &mut Vec<Diagnostic>,
89	) {
90	    let Some(target) = target else { return };
91	    let Some(load) = &seg.load else { return };
92	    let Some(addr_hex) = &load.address else {
93	        return;
94	    };
95	    let Ok(addr) = addr_hex.as_u32() else { return };
96	    let Some(end) = seg
97	        .size
98	        .as_ref()
99	        .and_then(SizeOrAuto::as_hex)
100	        .and_then(|h| h.as_u32().ok())
101	        .map(|sz| addr + sz)
102	    else {
103	        return;
104	    };
105	
106	    let r = &target.regions;
107	    let in_sram = inside(addr, end, &r.sram);
108	    let touches_ebr = overlaps(addr, end, &r.ebr_stack);
109	    let touches_mmio = overlaps(addr, end, &r.mmio);
110	    if !in_sram || touches_ebr || touches_mmio {
111	        out.push(layer_seg_err(
112	            ErrorCode(11),
113	            layer_name,
114	            seg.name.as_deref(),
115	            format!(
116	                "segment range [0x{addr:06X}..0x{end:06X}) escapes SRAM or touches reserved regions"
117	            ),
118	        ));
119	    }
120	}
121	
122	fn inside(addr: u32, end: u32, range: &MemRange) -> bool {
123	    let lo = range.start.as_u32().unwrap_or(0);
124	    let hi = range.end.as_u32().unwrap_or(0);
125	    addr >= lo && end <= hi.saturating_add(1)
126	}
127	
128	fn overlaps(addr: u32, end: u32, range: &MemRange) -> bool {
129	    let lo = range.start.as_u32().unwrap_or(0);
130	    let hi = range.end.as_u32().unwrap_or(0);
131	    !(end <= lo || addr > hi)
132	}

1	//! Structural rules E0001..E0009: scenario shape, layer
2	//! references, kind/load compatibility, UART size, halt
3	//! condition, patch target shape.
4	
5	use super::diagnostic::{Diagnostic, err, err_with_hint, layer_err, layer_err_with_hint};
6	use crate::config::{Config, Layer, LoadMethod, Patch, Scenario};
7	use crate::error::ErrorCode;
8	
9	pub(super) fn check_scenario_structural(
10	    cfg: &Config,
11	    scenario_name: &str,
12	    scen: &Scenario,
13	    out: &mut Vec<Diagnostic>,
14	) {
15	    if scen.layers.is_empty() {
16	        out.push(err(
17	            ErrorCode(1),
18	            format!("scenario `{scenario_name}` declares no layers"),
19	        ));
20	    }
21	    let run = scen.run.as_ref();
22	    let has_halt = run.and_then(|r| r.halt_on.as_ref()).is_some();
23	    let has_max = run.and_then(|r| r.max_cycles).is_some();
24	    if !has_halt && !has_max {
25	        out.push(err_with_hint(
26	            ErrorCode(8),
27	            format!("scenario `{scenario_name}` has no halt_on or max_cycles"),
28	            "set [scenarios.<name>.run].halt_on or .max_cycles".into(),
29	        ));
30	    }
31	    if !cfg.targets.contains_key(&scen.target) {
32	        out.push(err(
33	            ErrorCode(2),
34	            format!(
35	                "scenario `{scenario_name}` references undeclared target `{}`",
36	                scen.target
37	            ),
38	        ));
39	    }
40	}
41	
42	pub(super) fn check_layers(cfg: &Config, scen: &Scenario, out: &mut Vec<Diagnostic>) {
43	    for name in &scen.layers {
44	        let Some(layer) = cfg.layers.get(name) else {
45	            out.push(err(
46	                ErrorCode(2),
47	                format!("scenario references undeclared layer `{name}`"),
48	            ));
49	            continue;
50	        };
51	        check_kind_load_compat(name, layer, out);
52	        check_uart_size(name, layer, out);
53	        check_patches(name, layer, out);
54	    }
55	}
56	
57	fn check_kind_load_compat(name: &str, layer: &Layer, out: &mut Vec<Diagnostic>) {
58	    let Some(load) = &layer.load else { return };
59	    let kind = layer.kind.as_str();
60	    let bad_uart = matches!(
61	        kind,
62	        "assembler" | "binary" | "pcode" | "pcode-image" | "composite"
63	    ) && load.method == LoadMethod::Uart;
64	    if bad_uart {
65	        out.push(layer_err(
66	            ErrorCode(5),
67	            name,
68	            format!("kind `{kind}` cannot use load.method = \"uart\""),
69	        ));
70	    }
71	    if load.method == LoadMethod::Uart && load.max_bytes.is_none() {
72	        out.push(layer_err_with_hint(
73	            ErrorCode(4),
74	            name,
75	            "uart layer is missing load.max_bytes".into(),
76	            "set load.max_bytes = <hard cap>".into(),
77	        ));
78	    }
79	    if load.method == LoadMethod::Memory
80	        && load.address.is_none()
81	        && !layer.absolute_addresses
82	        && layer.segments.is_empty()
83	    {
84	        out.push(layer_err_with_hint(
85	            ErrorCode(15),
86	            name,
87	            "memory load with no address and no segments".into(),
88	            "set load.address or declare segments with claims".into(),
89	        ));
90	    }
91	}
92	
93	fn check_uart_size(name: &str, layer: &Layer, out: &mut Vec<Diagnostic>) {
94	    let Some(load) = &layer.load else { return };
95	    if load.method != LoadMethod::Uart {
96	        return;
97	    }
98	    let Some(max_bytes) = load.max_bytes else {
99	        return;
100	    };
101	    if let Some(input) = &layer.input
102	        && let Ok(meta) = std::fs::metadata(input)
103	        && meta.len() > max_bytes
104	    {
105	        out.push(layer_err(
106	            ErrorCode(4),
107	            name,
108	            format!(
109	                "uart input `{input}` ({} bytes) exceeds max_bytes ({max_bytes})",
110	                meta.len()
111	            ),
112	        ));
113	    }
114	}
115	
116	fn check_patches(name: &str, layer: &Layer, out: &mut Vec<Diagnostic>) {
117	    for p in &layer.patches {
118	        // Literal-hex target: verify it parses.
119	        if p.target.starts_with("0x") && crate::config::parse_hex_u32(&p.target).is_err() {
120	            out.push(layer_err(
121	                ErrorCode(6),
122	                name,
123	                format!("patch target `{}` is not a valid hex address", p.target),
124	            ));
125	        }
126	        // Cross-layer symbolic-target resolution lands in step 007.
127	        check_patch_value(name, p, out);
128	        check_patch_self_outside_segment(name, p, out);
129	    }
130	}
131	
132	fn check_patch_value(name: &str, p: &Patch, out: &mut Vec<Diagnostic>) {
133	    let v = p.value.as_str();
134	    if v == "self.address" || v == "self.end" || v == "self.size" {
135	        // E0016 enforced separately.
136	        return;
137	    }
138	    if v.starts_with("0x") && crate::config::parse_hex_u32(v).is_err() {
139	        out.push(layer_err(
140	            ErrorCode(6),
141	            name,
142	            format!("patch value `{v}` is not a valid hex literal"),
143	        ));
144	    }
145	}
146	
147	fn check_patch_self_outside_segment(name: &str, p: &Patch, out: &mut Vec<Diagnostic>) {
148	    let v = p.value.as_str();
149	    if v == "self.address" || v == "self.end" || v == "self.size" {
150	        out.push(layer_err_with_hint(
151	            ErrorCode(16),
152	            name,
153	            format!("patch value `{v}` only valid inside a segment block"),
154	            "move this patch into a [[layers.<n>.segments]] entry".into(),
155	        ));
156	    }
157	}

