//! Parser for `cor24-run --assemble` listing files.
//!
//! Each listing has two kinds of lines:
//!
//! - **Label**: leading whitespace, then `<symbol>:` (no other
//!   tokens). Examples: `                    _start:`,
//!   `                    eval_stack:`.
//! - **Data**: `<hex_addr>: <space-separated hex bytes>    <asm>`.
//!   Example: `0004: 2A 00 01 FF    la r1, 0xFF0100`.
//!
//! A label's address is the address of the next data line, OR if
//! no data line follows (e.g. trailing BSS reservation), the byte
//! immediately after the last data line.
//!
//! `Listing::resolve(symbol)` returns the absolute address as a
//! `u32`. Symbols that don't appear return `None`.

use std::collections::BTreeMap;

/// Parsed view of a `.lst` file: symbol -> absolute address.
#[derive(Debug, Default, Clone)]
pub struct Listing {
    symbols: BTreeMap<String, u32>,
}

impl Listing {
    /// Parse a listing-file string.
    pub fn parse(text: &str) -> Self {
        let mut symbols: BTreeMap<String, u32> = BTreeMap::new();
        let mut pending_labels: Vec<String> = Vec::new();
        let mut next_after_last_data: u32 = 0;
        for raw in text.lines() {
            if let Some(name) = parse_label_line(raw) {
                pending_labels.push(name);
                continue;
            }
            if let Some((addr, byte_count)) = parse_data_line(raw) {
                for label in pending_labels.drain(..) {
                    symbols.insert(label, addr);
                }
                next_after_last_data = addr.saturating_add(byte_count);
            }
        }
        // Trailing labels (BSS / .skip-only) take the end-of-data
        // address.
        for label in pending_labels {
            symbols.insert(label, next_after_last_data);
        }
        Listing { symbols }
    }

    /// Resolve a symbol to its absolute address.
    pub fn resolve(&self, symbol: &str) -> Option<u32> {
        self.symbols.get(symbol).copied()
    }
}

/// `                    <symbol>:` -> `Some("<symbol>")`.
fn parse_label_line(line: &str) -> Option<String> {
    let trimmed = line.trim();
    let body = trimmed.strip_suffix(':')?;
    if body.is_empty() {
        return None;
    }
    if !is_symbol_chars(body) {
        return None;
    }
    Some(body.to_string())
}

/// `0004: 2A 00 01 FF    la r1, 0xFF0100` -> `Some((0x0004, 4))`.
fn parse_data_line(line: &str) -> Option<(u32, u32)> {
    let trimmed = line.trim_start();
    let (addr_part, rest) = trimmed.split_once(':')?;
    if !addr_part.chars().all(|c| c.is_ascii_hexdigit()) {
        return None;
    }
    let addr = u32::from_str_radix(addr_part, 16).ok()?;
    // The bytes column ends before the disassembly. We count
    // pairs of hex digits separated by single spaces.
    let bytes_str = rest.split("   ").next().unwrap_or(rest).trim();
    let mut byte_count = 0u32;
    for tok in bytes_str.split_ascii_whitespace() {
        if tok.len() == 2 && tok.chars().all(|c| c.is_ascii_hexdigit()) {
            byte_count += 1;
        } else {
            break;
        }
    }
    Some((addr, byte_count))
}

fn is_symbol_chars(s: &str) -> bool {
    let mut chars = s.chars();
    let first = match chars.next() {
        Some(c) => c,
        None => return false,
    };
    if !(first.is_ascii_alphabetic() || first == '_') {
        return false;
    }
    chars.all(|c| c.is_ascii_alphanumeric() || c == '_')
}

