    let err = dispatch(cli).expect_err("should be unimplemented");
    match err {
        Error::NotImplemented { what, .. } => assert_eq!(what, expected),
        other => panic!("expected NotImplemented({expected}), got {other:?}"),
    }
}

fn s(name: &str) -> String {
