    assert_eq!(plan.segments[0].start, 0x0010);
    assert_eq!(plan.segments[0].end, 0x0010 + 0x0400);
    assert!(plan.segments[0].embedded);
    assert_eq!(plan.segments[1].start, 0x0410);
    assert_eq!(plan.segments[2].start, 0x0C10);
}

