        entry  = "0x000000"
        [scenarios.demo.run]
        max_cycles = 1
        [layers.high]
        kind = "binary"
        input = "high.bin"
        [layers.high.load]
        method = "memory"
        address = "0x010000"
        [layers.low]
        kind = "binary"
        input = "low.bin"
        [layers.low.load]
        method = "memory"
        address = "0x000000"
    "#;
    let cfg = parse(toml);
