#[test]
fn pcode_kind_memoizes_just_like_assembler() {
    let Some(no_op) = no_op_tool() else {
        eprintln!("/usr/bin/true not present; skipping");
        return;
    };
    let tmp = tempdir_utf8();
    let input = make_input(&tmp, "h.spc", b".end\n");
