}

fn collect_uart(
    layer_name: &str,
    layer: &crate::config::Layer,
    load: &crate::config::LoadSpec,
    plan: &mut LoadPlan,
) -> Result<()> {
    let bytes = if let Some(input) = &layer.input {
        std::fs::read(input).map_err(|source| Error::Io { source })?
