        Vec::new()
    };
    let terminator = load.terminator.as_deref().and_then(|n| match n {
        "EOT" => Some(0x04u8),
        "ETX" => Some(0x03u8),
        "EOF" => Some(0x1Au8),
        _ => None,
    });
