162	fn collect_layer(
163	    layer_name: &str,
164	    layer: &crate::config::Layer,
165	    artifacts: &Artifacts,
166	    scen: &Scenario,
167	    plan: &mut LoadPlan,
168	) -> Result<()> {
169	    if let Some(load) = &layer.load {
170	        match load.method {
171	            LoadMethod::Memory => collect_memory(layer_name, layer, load, artifacts, plan)?,
172	            LoadMethod::Uart => collect_uart(layer_name, layer, load, plan)?,
173	        }
174	    }
175	    let _ = scen; // used by step 009 once profile-relative claims resolve
176	    for (idx, seg) in layer.segments.iter().enumerate() {
177	        if let Some(rs) = resolve_segment(layer_name, idx, seg, layer, artifacts) {
178	            plan.segments.push(rs);
179	        }
180	    }
181	    Ok(())
182	}
