        .expect("binary built")
        .args(["run", "nested-demo", "--config", toml.to_str().unwrap()])
        .assert()
        .success()
        .stdout(contains("3"));
}

#[test]
fn run_with_oversized_source_fails_with_e0004() {
    let Some((out, build)) = skip_unless_ready() else {
        return;
