1	//! Build-tool invocation, per-process memoization, and listing
2	//! parsing.
3	//!
4	//! v1.2 (Phase 2): a single `Tool` struct covers both the COR24
5	//! assembler (`cor24-run --assemble`) and the p-code assembler
6	//! (`pa24r <input> -o <output>`). The kind is carried in
7	//! `ToolKind`; `build()` dispatches the argv accordingly.
8	//! Combining them into one struct keeps `tool.rs` under
9	//! sw-checklist's per-module function-count budget.
10	//!
11	//! `from_source` resolves the v1.2 schema's `[tools.<n>.source]`
12	//! kinds: `Path`, `FromPath { binary }`, `Sibling { path,
13	//! artifact }`. `Vendor` waits for Phase 4.
14	//!
15	//! The cache is in-memory and per-process: a single `sw-launch`
16	//! invocation that needs the same artifact twice spawns the tool
17	//! exactly once. Disk-persistent caching is Phase 4 work.
18	
19	use std::collections::{BTreeMap, HashMap};
20	use std::process::Command;
21	
22	use camino::{Utf8Path, Utf8PathBuf};
23	use sha2::{Digest, Sha256};
24	
25	use crate::error::{Error, Result};
26	
27	/// Which build tool this `Tool` wraps.
28	#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
29	pub enum ToolKind {
30	    /// `cor24-run --assemble <input> <out.bin> <out.lst>`
31	    Assembler,
32	    /// `pa24r <input> -o <out.p24>`
33	    Pcode,
34	    /// `p24-load <input.p24> -o <out.p24m> [--load-addr <addr>]`
35	    /// (caller passes `--load-addr` via `BuildJob.extra_args`).
36	    PcodeLinker,
37	}
38	
39	/// One build request: input source, where to write outputs,
40	/// extra command-line arguments to forward to the tool.
41	#[derive(Debug, Clone, PartialEq, Eq, Hash)]
42	pub struct BuildJob {
43	    pub layer_name: String,
44	    pub input: Utf8PathBuf,
45	    pub output_bin: Utf8PathBuf,
46	    pub output_lst: Utf8PathBuf,
47	    pub extra_args: Vec<String>,
48	}
49	
50	/// Result of one successful build.
51	#[derive(Debug, Clone, PartialEq, Eq)]
52	pub struct BuildOutput {
53	    pub artifact: Utf8PathBuf,
54	    pub listing: Utf8PathBuf,
55	    pub stdout: String,
56	    pub stderr: String,
57	}
58	
59	/// How a tool's binary path is discovered. Mirrors v1.2 schema's
60	/// `[tools.<n>.source]` block.
61	#[derive(Debug, Clone, PartialEq, Eq)]
62	pub enum SourceSpec {
63	    /// Absolute or repo-relative path to the binary.
64	    Path(Utf8PathBuf),
65	    /// Search `$PATH` for the named binary.
66	    FromPath { binary: String },
67	    /// Relative-to-config-dir path to a sibling repo, plus the
68	    /// artifact path within that sibling.
69	    Sibling {
70	        path: Utf8PathBuf,
71	        artifact: Utf8PathBuf,
72	    },
73	}
74	
75	/// Wraps either `cor24-run --assemble` or `pa24r`. The cache is
76	/// keyed by `(canonical tool_path, sha256(input), argv tail)`;
77	/// two calls with byte-identical inputs and arguments hit the
78	/// cache.
79	#[derive(Debug)]
80	pub struct Tool {
81	    /// The host binary on disk.
82	    pub tool_path: Utf8PathBuf,
83	    /// Which tool this wraps.
84	    pub kind: ToolKind,
85	    cache: HashMap<CacheKey, BuildOutput>,
86	    /// Number of times the tool has actually been spawned by this
87	    /// `Tool` instance. Tests use it to verify memoization.
88	    pub spawn_count: usize,
89	}
90	
91	#[derive(Debug, Clone, PartialEq, Eq, Hash)]
92	struct CacheKey {
93	    tool_path: String,
94	    input_sha: String,
95	    args: Vec<String>,
96	}
97	
98	/// Backward-compat alias so step-007 / step-009 call sites that
99	/// say `Assembler::*` keep working.
100	pub type Assembler = Tool;
101	
102	impl Tool {
103	    /// Construct a `Tool` wrapping the binary at `tool_path` with
104	    /// the given kind. Default kind for backward compat is
105	    /// `ToolKind::Assembler`; pass `ToolKind::Pcode` for `pa24r`.
106	    pub fn new(tool_path: impl Into<Utf8PathBuf>) -> Self {
107	        Tool {
108	            tool_path: tool_path.into(),
109	            kind: ToolKind::Assembler,
110	            cache: HashMap::new(),
111	            spawn_count: 0,
112	        }
113	    }
114	
115	    /// Resolve a `SourceSpec` against the config file's directory
116	    /// and the tool kind, returning a constructed `Tool`.
117	    pub fn from_source(spec: &SourceSpec, config_dir: &Utf8Path, kind: ToolKind) -> Result<Self> {
118	        let tool_path = match spec {
119	            SourceSpec::Path(p) => {
120	                if p.is_absolute() {
121	                    p.clone()
122	                } else {
123	                    config_dir.join(p)
124	                }
125	            }
126	            SourceSpec::FromPath { binary } => find_binary_on_path(binary)?,
127	            SourceSpec::Sibling { path, artifact } => {
128	                let sibling_root = config_dir.join(path);
129	                let resolved = sibling_root.join(artifact);
130	                if !resolved.is_file() {
131	                    return Err(Error::cli(format!(
132	                        "sibling tool not found at `{resolved}`"
133	                    )));
134	                }
135	                resolved
136	            }
137	        };
138	        Ok(Tool {
139	            tool_path,
140	            kind,
141	            cache: HashMap::new(),
142	            spawn_count: 0,
143	        })
144	    }
145	
146	    /// Build a `job`: hit the in-process cache or spawn the tool.
147	    pub fn build(&mut self, job: &BuildJob) -> Result<BuildOutput> {
148	        let key = CacheKey {
149	            tool_path: self
150	                .tool_path
151	                .canonicalize_utf8()
152	                .unwrap_or_else(|_| self.tool_path.clone())
153	                .to_string(),
154	            input_sha: hash_file_sha256(&job.input)?,
155	            args: job.extra_args.clone(),
156	        };
157	        if let Some(cached) = self.cache.get(&key) {
158	            return Ok(cached.clone());
159	        }
160	        for p in [job.output_bin.parent(), job.output_lst.parent()]
161	            .into_iter()
162	            .flatten()
163	        {
164	            std::fs::create_dir_all(p).map_err(|source| Error::Io { source })?;
165	        }
166	        let (in_p, out_p, lst_p) = (
167	            job.input.as_std_path(),
168	            job.output_bin.as_std_path(),
169	            job.output_lst.as_std_path(),
170	        );
171	        let mut cmd = Command::new(self.tool_path.as_std_path());
172	        match self.kind {
173	            ToolKind::Assembler => cmd.args(["--assemble".as_ref(), in_p, out_p, lst_p]),
174	            ToolKind::Pcode => cmd.args([in_p, "-o".as_ref(), out_p]),
175	            ToolKind::PcodeLinker => cmd.args([in_p, "-o".as_ref(), out_p]),
176	        };
177	        cmd.args(&job.extra_args);
178	        let output = cmd.output().map_err(|source| Error::Io { source })?;
179	        self.spawn_count += 1;
180	        if !output.status.success() {
181	            let stderr = String::from_utf8_lossy(&output.stderr);
182	            return Err(Error::cli(format!(
183	                "{} exited with {}: {stderr}",
184	                self.tool_path, output.status
185	            )));
186	        }
187	        let listing = match self.kind {
188	            ToolKind::Assembler => job.output_lst.clone(),
189	            ToolKind::Pcode | ToolKind::PcodeLinker => Utf8PathBuf::new(),
190	        };
191	        let out = BuildOutput {
192	            artifact: job.output_bin.clone(),
193	            listing,
194	            stdout: String::from_utf8_lossy(&output.stdout).into_owned(),
195	            stderr: String::from_utf8_lossy(&output.stderr).into_owned(),
196	        };
197	        self.cache.insert(key, out.clone());
198	        Ok(out)
199	    }
200	}
201	
202	/// Compute the SHA-256 of a file's contents, hex-encoded.
203	pub fn hash_file_sha256(path: &Utf8Path) -> Result<String> {
204	    let bytes = std::fs::read(path).map_err(|source| Error::Io { source })?;
205	    let mut hasher = Sha256::new();
206	    hasher.update(&bytes);
207	    let digest = hasher.finalize();
208	    let mut hex = String::with_capacity(digest.len() * 2);
209	    for b in digest {
210	        use std::fmt::Write;
211	        let _ = write!(hex, "{b:02x}");
212	    }
213	    Ok(hex)
214	}
215	
216	/// Search `$PATH` for `binary`. Returns the first match.
217	pub fn find_binary_on_path(binary: &str) -> Result<Utf8PathBuf> {
218	    let paths = std::env::var_os("PATH").ok_or_else(|| Error::cli("PATH unset"))?;
219	    for dir in std::env::split_paths(&paths) {
220	        let candidate = dir.join(binary);
221	        if candidate.is_file() {
222	            return Utf8PathBuf::from_path_buf(candidate)
223	                .map_err(|p| Error::cli(format!("non-UTF8 {binary} path: {p:?}")));
224	        }
225	    }
226	    Err(Error::cli(format!("{binary} not found on PATH")))
227	}
228	
229	// ---------- Listing parser -----------------------------------------
230	
231	/// Parsed view of a `cor24-run --assemble` `.lst` file: maps each
232	/// emitted symbol to its absolute address.
233	#[derive(Debug, Default, Clone)]
234	pub struct Listing {
235	    symbols: BTreeMap<String, u32>,
236	}
237	
238	impl Listing {
239	    /// Parse a listing-file string.
240	    pub fn parse(text: &str) -> Self {
241	        let mut symbols: BTreeMap<String, u32> = BTreeMap::new();
242	        let mut pending: Vec<String> = Vec::new();
243	        let mut next_after_last_data: u32 = 0;
244	        for raw in text.lines() {
245	            let trimmed = raw.trim();
246	            if let Some(body) = trimmed.strip_suffix(':')
247	                && !body.is_empty()
248	                && body
249	                    .chars()
250	                    .next()
251	                    .is_some_and(|c| c.is_ascii_alphabetic() || c == '_')
252	                && body
253	                    .chars()
254	                    .skip(1)
255	                    .all(|c| c.is_ascii_alphanumeric() || c == '_')
256	            {
257	                pending.push(body.to_string());
258	                continue;
259	            }
260	            let trimmed_left = raw.trim_start();
261	            if let Some((addr_part, rest)) = trimmed_left.split_once(':')
262	                && addr_part.chars().all(|c| c.is_ascii_hexdigit())
263	                && let Ok(addr) = u32::from_str_radix(addr_part, 16)
264	            {
265	                let bytes_str = rest.split("   ").next().unwrap_or(rest).trim();
266	                let count = bytes_str
267	                    .split_ascii_whitespace()
268	                    .take_while(|t| t.len() == 2 && t.chars().all(|c| c.is_ascii_hexdigit()))
269	                    .count() as u32;
270	                for label in pending.drain(..) {
271	                    symbols.insert(label, addr);
272	                }
273	                next_after_last_data = addr.saturating_add(count);
274	            }
275	        }
276	        for label in pending {
277	            symbols.insert(label, next_after_last_data);
278	        }
279	        Listing { symbols }
280	    }
281	
282	    /// Resolve a symbol to its absolute address.
283	    pub fn resolve(&self, symbol: &str) -> Option<u32> {
284	        self.symbols.get(symbol).copied()
285	    }
286	}
