        let memo = MemoKey {
            tool_path: canon.to_string(),
            input_sha: input_sha.clone(),
            args: job.extra_args.clone(),
        };
        if let Some(cached) = self.cache.get(&memo) {
            return Ok(cached.clone());
        }
        let want_listing = self.kind == ToolKind::Assembler;
