    // produced artifact paths appear on stdout.
    let path_var = std::env::var_os("PATH").unwrap_or_default();
    let on_path = |bin: &str| std::env::split_paths(&path_var).any(|p| p.join(bin).is_file());
    if !on_path("cor24-run") || !on_path("pa24r") {
