1	//! Content-addressed disk cache for sw-launcher build artifacts.
2	//!
3	//! Phase 4 step 1 promotes the in-process `HashMap` cache to a
4	//! disk-persistent store under
5	//! `${XDG_CACHE_HOME:-$HOME/.cache}/sw-launch/`:
6	//!
7	//! ```text
8	//! artifacts/<digest>/
9	//!   <stem>.<ext>           # the artifact bytes
10	//!   <stem>.lst             # listing (Assembler kind only)
11	//!   provenance.toml        # cache key fields + timestamp + host
12	//! locks/<digest>.lock      # advisory file lock for serialization
13	//! ```
14	//!
15	//! `Cache::get_or_fill` is the entry point: it acquires an
16	//! exclusive lock on `locks/<digest>.lock`, checks for a fresh
17	//! entry under `artifacts/<digest>/`, and on miss runs a
18	//! caller-supplied `fill` closure into a temp directory before
19	//! atomically renaming it into place.
20	//!
21	//! Verification on read: `provenance.toml` records the SHA-256 of
22	//! every artifact byte the closure produced; reads re-hash the
23	//! files and re-fill if they don't match (defends against partial
24	//! writes that survived a crash, or manual edits to the cache
25	//! directory).
26	
27	use std::fs::{File, OpenOptions};
28	use std::io::Write;
29	use std::path::{Path, PathBuf};
30	use std::time::{SystemTime, UNIX_EPOCH};
31	
32	use anyhow::{Context, Result, anyhow};
33	use camino::Utf8PathBuf;
34	use serde::{Deserialize, Serialize};
35	use sha2::{Digest, Sha256};
36	
37	/// One cache lookup. The `digest()` method canonicalizes the key
38	/// to a hex sha256 used as the on-disk directory name.
39	#[derive(Debug, Clone, PartialEq, Eq)]
40	pub struct CacheKey {
41	    pub tool_path: Utf8PathBuf,
42	    pub input_sha: String,
43	    pub extra_args: Vec<String>,
44	    pub output_stem: String,
45	    pub output_ext: String,
46	    /// Whether the tool also emits a `.lst` listing alongside the
47	    /// main artifact. Affects which files the cache verifies.
48	    pub with_listing: bool,
49	}
50	
51	impl CacheKey {
52	    /// SHA-256 over a canonical encoding of every key field.
53	    pub fn digest(&self) -> String {
54	        let mut hasher = Sha256::new();
55	        hasher.update(self.tool_path.as_str().as_bytes());
56	        hasher.update(b"\x00");
57	        hasher.update(self.input_sha.as_bytes());
58	        hasher.update(b"\x00");
59	        for a in &self.extra_args {
60	            hasher.update(a.as_bytes());
61	            hasher.update(b"\x00");
62	        }
63	        hasher.update(b"\x00");
64	        hasher.update(self.output_stem.as_bytes());
65	        hasher.update(b"\x00");
66	        hasher.update(self.output_ext.as_bytes());
67	        hasher.update(b"\x00");
68	        hasher.update(if self.with_listing { b"L" } else { b"-" });
69	        let d = hasher.finalize();
70	        let mut hex = String::with_capacity(d.len() * 2);
71	        for b in d {
72	            use std::fmt::Write;
73	            let _ = write!(hex, "{b:02x}");
74	        }
75	        hex
76	    }
77	}
78	
79	/// One on-disk entry: the directory holding the cached files and
80	/// the deserialized provenance record alongside.
81	#[derive(Debug, Clone)]
82	pub struct CacheEntry {
83	    pub dir: PathBuf,
84	    pub provenance: Provenance,
85	}
86	
87	/// Metadata recorded next to the cached artifact.
88	///
89	/// `layer_name` is informational: it records which layer most
90	/// recently filled this entry, for `cache list` to print a useful
91	/// column. It does NOT participate in `CacheKey::digest`, so two
92	/// scenarios that build the same input bytes share one cache
93	/// entry regardless of layer-name.
94	#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
95	pub struct Provenance {
96	    pub schema_version: u32,
97	    pub tool_path: String,
98	    pub input_sha256: String,
99	    pub extra_args: Vec<String>,
100	    pub output_stem: String,
101	    pub output_ext: String,
102	    pub with_listing: bool,
103	    pub artifact_sha256: String,
104	    pub listing_sha256: Option<String>,
105	    pub created_unix: u64,
106	    pub host: String,
107	    #[serde(default)]
108	    pub layer_name: Option<String>,
109	}
110	
111	/// Disk cache rooted at a directory.
112	#[derive(Debug, Clone)]
113	pub struct Cache {
114	    root: PathBuf,
115	}
116	
117	impl Cache {
118	    /// Open the default cache at `${XDG_CACHE_HOME:-$HOME/.cache}/sw-launch/`,
119	    /// honoring `SW_LAUNCH_CACHE_DIR` as an override.
120	    pub fn open_default() -> Result<Self> {
121	        let root = if let Some(p) = std::env::var_os("SW_LAUNCH_CACHE_DIR") {
122	            PathBuf::from(p)
123	        } else if let Some(p) = std::env::var_os("XDG_CACHE_HOME") {
124	            PathBuf::from(p).join("sw-launch")
125	        } else {
126	            let home = std::env::var_os("HOME")
127	                .ok_or_else(|| anyhow!("HOME unset; cannot resolve cache dir"))?;
128	            PathBuf::from(home).join(".cache").join("sw-launch")
129	        };
130	        Self::open_at(root)
131	    }
132	
133	    /// Open a cache rooted at `root`. Creates the directory tree
134	    /// if needed.
135	    pub fn open_at(root: PathBuf) -> Result<Self> {
136	        std::fs::create_dir_all(root.join("artifacts"))
137	            .with_context(|| format!("create {}/artifacts", root.display()))?;
138	        std::fs::create_dir_all(root.join("locks"))
139	            .with_context(|| format!("create {}/locks", root.display()))?;
140	        Ok(Cache { root })
141	    }
142	
143	    /// Look up `key`. On hit, return the entry. On miss (or
144	    /// corruption), acquire an exclusive lock, run `fill`, atomically
145	    /// commit the result, and return the entry.
146	    ///
147	    /// `fill` writes its output files (`<stem>.<ext>` and optionally
148	    /// `<stem>.lst`) into the directory passed to it. The cache
149	    /// verifies their presence and records SHA-256 sums in
150	    /// `provenance.toml`.
151	    pub fn get_or_fill<F>(&self, key: &CacheKey, fill: F) -> Result<CacheEntry>
152	    where
153	        F: FnOnce(&Path) -> Result<()>,
154	    {
155	        self.get_or_fill_with(key, None, fill)
156	    }
157	
158	    /// Like [`Cache::get_or_fill`] but also records `layer_name` in
159	    /// the entry's `provenance.toml` (informational only; does not
160	    /// affect the cache key digest).
161	    pub fn get_or_fill_with<F>(
162	        &self,
163	        key: &CacheKey,
164	        layer_name: Option<&str>,
165	        fill: F,
166	    ) -> Result<CacheEntry>
167	    where
168	        F: FnOnce(&Path) -> Result<()>,
169	    {
170	        let digest = key.digest();
171	        let final_dir = self.root.join("artifacts").join(&digest);
172	        let lock_path = self.root.join("locks").join(format!("{digest}.lock"));
173	        let lock = OpenOptions::new()
174	            .create(true)
175	            .write(true)
176	            .truncate(false)
177	            .open(&lock_path)
178	            .with_context(|| format!("open lock {}", lock_path.display()))?;
179	        lock.lock()
180	            .with_context(|| format!("flock {}", lock_path.display()))?;
181	        if let Some(entry) = self.read_if_fresh(key, &final_dir)? {
182	            return Ok(entry);
183	        }
184	        let temp_dir = self.root.join("artifacts").join(format!(".tmp-{digest}"));
185	        let _ = std::fs::remove_dir_all(&temp_dir);
186	        std::fs::create_dir_all(&temp_dir)
187	            .with_context(|| format!("create temp {}", temp_dir.display()))?;
188	        fill(&temp_dir).context("cache fill closure")?;
189	        let prov = self.write_provenance(key, &temp_dir, layer_name)?;
190	        let _ = std::fs::remove_dir_all(&final_dir);
191	        std::fs::rename(&temp_dir, &final_dir)
192	            .with_context(|| format!("rename {} -> {}", temp_dir.display(), final_dir.display()))?;
193	        Ok(CacheEntry {
194	            dir: final_dir,
195	            provenance: prov,
196	        })
197	    }
198	
