    pub key: String,
    pub resolved_path: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub vendor_repo: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub vendor_sha: Option<String>,
    pub input_sha256: String,
    pub synced_at: String,
}

