#[derive(Debug, Clone, PartialEq, Eq)]
pub enum EntryStatus {
    /// On-disk sha matches the lockfile.
    Fresh,
    /// File present but sha mismatch.
    Drifted {
        recorded: String,
        observed: String,
    },
    /// `resolved_path` doesn't exist any more (E0042).
    Unresolvable,
    /// File present but couldn't be read (permission, etc).
    Unverified(String),
}

impl Default for Lockfile {
    fn default() -> Self {
        Lockfile {
            schema_version: 1,
            vendored: Vec::new(),
        }
    }
}

impl Lockfile {
    /// Read a lockfile from `path`.
    pub fn read(path: &Path) -> Result<Self> {
        let text = std::fs::read_to_string(path)
            .with_context(|| format!("read {}", path.display()))?;
        let lf: Lockfile = toml::from_str(&text)
            .with_context(|| format!("parse {} as TOML", path.display()))?;
        Ok(lf)
