    /// Lookup helper for E0041 enforcement: returns `Some(Drifted)`
    /// or `Some(Unresolvable)` for the input at `resolved_path`,
    /// or None if the path matches the recorded sha.
    pub fn drift_for(&self, resolved_path: &Path) -> Option<EntryStatus> {
        let canonical = canonicalize(resolved_path);
