[project]
name = "vendor-test"

[targets.cor24]
kind = "emulator"
word_bits = 24
address_bits = 24
endian = "big"
loader = "cor24-memory-map"

[targets.cor24.regions]
sram = { start = "0x000000", end = "0x0FFFFF" }

[scenarios.demo]
