layers = ["thing"]
entry  = "0x000000"

[scenarios.demo.run]
mode       = "batch"
timeout_ms = 1000
max_cycles = 1000
halt_on    = "monitor-exit"

[layers.thing]
kind = "binary"
input = "thing.bin"
[layers.thing.load]
method  = "memory"
address = "0x000000"
"#;
    std::fs::write(dir.join("sw-launch.toml"), toml).unwrap();
    std::fs::write(dir.join("thing.bin"), b"hello").unwrap();
}

fn cmd(dir: &Path) -> Command {
    let mut c = Command::cargo_bin("sw-launch").expect("binary built");
    c.current_dir(dir);
    c
}

