1	//! `sw-launch.lock` writer / reader and drift detection.
2	//!
3	//! Phase 4 step 3 lands the lockfile so sibling-repo
4	//! dependencies (vendored COR24 binaries, the OCaml runtime,
5	//! the p-code VM source) are pinned across machines and CI.
6	//!
7	//! Layout (one [[vendored]] table per distinct input across all
8	//! scenarios, sorted by `key`):
9	//!
10	//! ```toml
11	//! schema_version = 1
12	//!
13	//! [[vendored]]
14	//! key           = "sw-cor24-pcode/vm/pvm.s"
15	//! resolved_path = "/abs/path/at/sync/time/pvm.s"
16	//! vendor_repo   = "sw-embed/sw-cor24-pcode"      # if known
17	//! vendor_sha    = "abc1234..."                    # if .git
18	//! input_sha256  = "..."                           # 64 hex
19	//! synced_at     = "2026-04-30T12:00:00Z"
20	//! ```
21	//!
22	//! `vendor sync` writes the file. `vendor status` reads it and
23	//! reports drift. `sw-launch run`/`build` consult it via
24	//! `Lockfile::status` and refuse to proceed on stale entries
25	//! (E0041) unless `--update-lock` is passed.
26	
27	use std::collections::BTreeMap;
28	use std::path::{Path, PathBuf};
29	
30	use anyhow::{Context, Result, anyhow};
31	use camino::{Utf8Path, Utf8PathBuf};
32	use serde::{Deserialize, Serialize};
33	use sw_launcher_tool::tool::hash_file_sha256;
34	
35	/// The on-disk lockfile, deserialized.
36	#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
37	pub struct Lockfile {
38	    pub schema_version: u32,
39	    #[serde(default)]
40	    pub vendored: Vec<VendoredEntry>,
41	}
42	
43	/// One pinned input.
44	#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
45	pub struct VendoredEntry {
46	    pub key: String,
47	    pub resolved_path: String,
48	    #[serde(default, skip_serializing_if = "Option::is_none")]
49	    pub vendor_repo: Option<String>,
50	    #[serde(default, skip_serializing_if = "Option::is_none")]
51	    pub vendor_sha: Option<String>,
52	    pub input_sha256: String,
53	    pub synced_at: String,
54	}
55	
56	/// Per-entry comparison result returned by [`Lockfile::status`].
57	#[derive(Debug, Clone, PartialEq, Eq)]
58	pub enum EntryStatus {
59	    /// On-disk sha matches the lockfile.
60	    Fresh,
61	    /// File present but sha mismatch.
62	    Drifted { recorded: String, observed: String },
63	    /// `resolved_path` doesn't exist any more (E0042).
64	    Unresolvable,
65	    /// File present but couldn't be read (permission, etc).
66	    Unverified(String),
67	}
68	
69	impl Default for Lockfile {
70	    fn default() -> Self {
71	        Lockfile {
72	            schema_version: 1,
73	            vendored: Vec::new(),
74	        }
75	    }
76	}
77	
78	impl Lockfile {
79	    /// Read a lockfile from `path`.
80	    pub fn read(path: &Path) -> Result<Self> {
81	        let text =
82	            std::fs::read_to_string(path).with_context(|| format!("read {}", path.display()))?;
83	        let lf: Lockfile =
84	            toml::from_str(&text).with_context(|| format!("parse {} as TOML", path.display()))?;
85	        Ok(lf)
86	    }
87	
88	    /// Read a lockfile if it exists; otherwise return None.
89	    pub fn read_optional(path: &Path) -> Result<Option<Self>> {
90	        if !path.is_file() {
91	            return Ok(None);
92	        }
93	        Self::read(path).map(Some)
94	    }
95	
96	    /// Serialize and write atomically (temp file + rename).
97	    pub fn write(&self, path: &Path) -> Result<()> {
98	        let text = self.to_toml_string();
99	        let tmp = path.with_extension("lock.tmp");
100	        std::fs::write(&tmp, &text).with_context(|| format!("write {}", tmp.display()))?;
101	        std::fs::rename(&tmp, path)
102	            .with_context(|| format!("rename {} -> {}", tmp.display(), path.display()))?;
103	        Ok(())
104	    }
105	
106	    /// Render the lockfile as a stable canonical TOML string.
107	    /// Vendored entries are emitted sorted by `key`.
108	    pub fn to_toml_string(&self) -> String {
109	        let mut sorted = self.vendored.clone();
110	        sorted.sort_by(|a, b| a.key.cmp(&b.key));
111	        let canonical = Lockfile {
112	            schema_version: self.schema_version,
113	            vendored: sorted,
114	        };
115	        toml::to_string_pretty(&canonical).expect("Lockfile is always TOML-serializable")
116	    }
117	
118	    /// Compare every recorded entry against the file at its
119	    /// `resolved_path`. Returns one [`EntryStatus`] per entry, in
120	    /// declaration order.
121	    pub fn status(&self) -> Vec<(String, EntryStatus)> {
122	        self.vendored
123	            .iter()
124	            .map(|e| (e.key.clone(), check_entry(e)))
125	            .collect()
126	    }
127	
128	    /// Lookup helper for E0041 enforcement: returns `Some(Drifted)`
129	    /// or `Some(Unresolvable)` for the input at `resolved_path`,
130	    /// or None if the path matches the recorded sha.
131	    pub fn drift_for(&self, resolved_path: &Path) -> Option<EntryStatus> {
132	        let canonical = canonicalize(resolved_path);
133	        for e in &self.vendored {
134	            if canonicalize(Path::new(&e.resolved_path)) == canonical {
135	                let s = check_entry(e);
136	                return match s {
137	                    EntryStatus::Fresh => None,
138	                    other => Some(other),
139	                };
140	            }
141	        }
142	        None
143	    }
144	}
145	
146	fn check_entry(e: &VendoredEntry) -> EntryStatus {
147	    let path = Path::new(&e.resolved_path);
148	    if !path.is_file() {
149	        return EntryStatus::Unresolvable;
150	    }
151	    let utf8 = match Utf8Path::from_path(path) {
152	        Some(p) => p,
153	        None => return EntryStatus::Unverified("non-UTF8 path".into()),
154	    };
155	    match hash_file_sha256(utf8) {
156	        Ok(observed) => {
157	            if observed == e.input_sha256 {
158	                EntryStatus::Fresh
159	            } else {
160	                EntryStatus::Drifted {
161	                    recorded: e.input_sha256.clone(),
162	                    observed,
163	                }
164	            }
165	        }
166	        Err(err) => EntryStatus::Unverified(format!("{err:#}")),
167	    }
168	}
169	
170	fn canonicalize(p: &Path) -> PathBuf {
171	    p.canonicalize().unwrap_or_else(|_| p.to_path_buf())
172	}
