174	/// One input the lockfile should record. Callers (`vendor sync`)
175	/// build a `Vec<VendorInput>` by walking the manifest's layers
176	/// and tools.
177	#[derive(Debug, Clone)]
178	pub struct VendorInput {
179	    /// Stable, repo-relative key. For sibling-repo files,
180	    /// `<sibling-relpath>/<artifact>`. For FromPath tool binaries,
181	    /// the binary name.
182	    pub key: String,
183	    /// Absolute on-disk path resolved at sync time.
184	    pub resolved_path: Utf8PathBuf,
185	    /// Owning repo identifier ("org/repo"), if discoverable.
186	    pub vendor_repo: Option<String>,
187	}
188	
189	/// Build a fresh `Lockfile` by hashing every `VendorInput`.
190	/// `now_iso8601` is supplied by the caller so tests can pin it.
191	pub fn sync(inputs: &[VendorInput], now_iso8601: &str) -> Result<Lockfile> {
192	    let mut by_key: BTreeMap<String, VendoredEntry> = BTreeMap::new();
193	    for inp in inputs {
194	        if !inp.resolved_path.as_std_path().is_file() {
195	            return Err(anyhow!(
196	                "vendor input `{}` does not resolve to a file at `{}`",
197	                inp.key,
198	                inp.resolved_path
199	            ));
200	        }
201	        let sha = hash_file_sha256(&inp.resolved_path)?;
202	        let entry = VendoredEntry {
203	            key: inp.key.clone(),
204	            resolved_path: inp.resolved_path.to_string(),
205	            vendor_repo: inp.vendor_repo.clone(),
206	            vendor_sha: read_git_head(&inp.resolved_path),
207	            input_sha256: sha,
208	            synced_at: now_iso8601.to_string(),
209	        };
210	        by_key.insert(inp.key.clone(), entry);
211	    }
212	    Ok(Lockfile {
213	        schema_version: 1,
214	        vendored: by_key.into_values().collect(),
215	    })
216	}
