fn format_json(results: &[CheckResult]) -> String {
    let mut out = String::from("[");
    for (i, r) in results.iter().enumerate() {
        if i > 0 {
            out.push(',');
        }
        let detail = r.detail.replace('\\', "\\\\").replace('"', "\\\"");
        out.push_str(&format!(
