            for term in [&p.target, &p.value] {
                if let Some(rel) = term.strip_prefix("sidecar:") {
                    let resolved: Utf8PathBuf = if Utf8Path::new(rel).is_absolute() {
                        Utf8PathBuf::from(rel)
