81	        let text =
82	            std::fs::read_to_string(path).with_context(|| format!("read {}", path.display()))?;
83	        let lf: Lockfile =
84	            toml::from_str(&text).with_context(|| format!("parse {} as TOML", path.display()))?;
85	        Ok(lf)
86	    }
