88	    /// Read a lockfile if it exists; otherwise return None.
89	    pub fn read_optional(path: &Path) -> Result<Option<Self>> {
90	        if !path.is_file() {
91	            return Ok(None);
92	        }
93	        Self::read(path).map(Some)
94	    }
