96	    /// Serialize and write atomically (temp file + rename).
97	    pub fn write(&self, path: &Path) -> Result<()> {
98	        let text = self.to_toml_string();
99	        let tmp = path.with_extension("lock.tmp");
100	        std::fs::write(&tmp, &text).with_context(|| format!("write {}", tmp.display()))?;
101	        std::fs::rename(&tmp, path)
102	            .with_context(|| format!("rename {} -> {}", tmp.display(), path.display()))?;
