106	    /// Render the lockfile as a stable canonical TOML string.
107	    /// Vendored entries are emitted sorted by `key`.
108	    pub fn to_toml_string(&self) -> String {
109	        let mut sorted = self.vendored.clone();
110	        sorted.sort_by(|a, b| a.key.cmp(&b.key));
111	        let canonical = Lockfile {
112	            schema_version: self.schema_version,
