129	fn check_entry(e: &VendoredEntry) -> EntryStatus {
130	    let path = Path::new(&e.resolved_path);
131	    if !path.is_file() {
132	        return EntryStatus::Unresolvable;
133	    }
134	    let utf8 = match Utf8Path::from_path(path) {
135	        Some(p) => p,
136	        None => return EntryStatus::Unverified("non-UTF8 path".into()),
137	    };
138	    match hash_file_sha256(utf8) {
139	        Ok(observed) => {
140	            if observed == e.input_sha256 {
141	                EntryStatus::Fresh
142	            } else {
