51	/// Run the full check suite. Returns Err only on internal IO
52	/// errors -- regular check failures surface in the printed
53	/// report and the exit code.
54	pub fn run(config: Option<&Utf8Path>, json: bool) -> Result<()> {
55	    let mut results: Vec<CheckResult> = Vec::new();
56	    results.push(check_tool_with_version("cor24-run", true));
57	    results.push(check_tool_on_path("pa24r"));
58	    results.push(check_tool_on_path("p24-load"));
