64	                results.extend(check_manifest_inputs(&cfg, cfg_dir));
65	                results.push(check_lockfile(cfg_dir));
66	            }
67	            Err(e) => results.push(CheckResult {
68	                name: "manifest",
69	                status: Status::Fail,
